export function trialLabels(language='EN'){const i=Math.max(0,trialLanguages.indexOf(language));return Object.fromEntries(Object.entries(trialWords).map(([k,v])=>[k,v.split('|')[i]||v.split('|')[0]]));}

export function attachTrialBench({getLanguage=()=> 'EN',onRecipe=()=>{},onCompare=async()=>false,storage=globalThis.localStorage}={}){
 const host=document.getElementById('continue-home')||document.querySelector('.custom-library-toolbar');if(!host||document.getElementById('trial-bench'))return null;
 let store=createTrialStore(storage),current=store.list().at(-1)||createTrialProject(),pending=false,statusKey=store.problem()?'failed':'',armed=null,views=[],compareA='',compareB='';const previews=new Map(),fields=new Map();
 const t=()=>trialLabels(getLanguage()),el=(tag,text='',cls='')=>{const n=document.createElement(tag);n.textContent=text;if(cls)n.className=cls;return n;};
 const root=el('details','','trial-bench');root.id='trial-bench';const summary=el('summary'),body=el('div','','tb-body');root.append(summary,body);host.after(root);const launcher=el('button');launcher.id='trial-bench-launcher';launcher.type='button';launcher.addEventListener('click',()=>open());document.querySelector('.custom-library-toolbar')?.append(launcher);
 const status=el('p','','tb-status');status.setAttribute('role','status');status.setAttribute('aria-live','polite');let projectSelect,compareSelectA,compareSelectB,compareButton;
 function open(){root.open=true;root.scrollIntoView({behavior:'smooth',block:'start'});}
 function notify(key){statusKey=key;status.textContent=t()[key]||'';}
 const emit=type=>document.dispatchEvent?.(new CustomEvent(type,{detail:{kind:'trial',id:current.id}}));
 function save(){try{current=store.save(current);pending=false;notify('saved');updateProjects();emit('prompt-studio-work-changed');return true;}catch(error){pending=true;notify(['conflict','limit'].includes(error.message)?error.message:'failed');return false;}}
 const canLeave=()=>!pending||globalThis.confirm(t().unsaved);
 function release(id){const preview=previews.get(id);if(preview?.local)URL.revokeObjectURL(preview.url);previews.delete(id);}
 function clearPreviews(){for(const id of [...previews.keys()])release(id);}
 function select(p){clearPreviews();current=normalizeTrialProject(p);pending=false;armed=null;compareA=compareB='';statusKey='';render();emit('prompt-studio-work-opened');}
 function updateProjects(){if(!projectSelect)return;const all=store.list();if(!all.some(p=>p.id===current.id))all.push(current);projectSelect.replaceChildren(...all.map(p=>new Option(p.id===current.id?current.title:p.title,p.id)));projectSelect.value=current.id;}
 function button(parent,key,fn){const b=el('button',t()[key]);b.type='button';b.dataset.tbAction=key;b.addEventListener('click',fn);parent.append(b);return b;}
 function field(parent,key,value,type,fn,options=[]){const label=el('label'),caption=el('span',t()[key]||key),n=el(type==='textarea'?'textarea':type==='select'?'select':'input');if(type==='select'){n.append(...options.map(x=>new Option(t()[x]||x,x)));}else n.type=type||'text';n.value=value;n.dataset.tbField=key;if(type==='textarea')n.rows=3;n.addEventListener(type==='select'?'change':'input',()=>fn(n.value));label.append(caption,n);parent.append(label);fields.set(key,n);return n;}
 async function copy(text){try{await navigator.clipboard.writeText(text);notify('copied');}catch{notify('failed');}}
 function download(text,extension){const url=URL.createObjectURL(new Blob([text],{type:extension==='json'?'application/json':'text/plain;charset=utf-8'})),a=el('a');a.href=url;a.download='PromptStudio_trial.'+extension;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function changed(fn){fn();save();refreshCards();}
 function showPreview(container,v){container.replaceChildren();const preview=previews.get(v.id);if(!preview)return;const media=el(v.result?.kind==='video'?'video':'img');media.src=preview.url;if(media.tagName==='VIDEO'){media.controls=true;media.preload='metadata';}else{media.alt=v.result?.filename||'';media.loading='lazy';}container.append(media);}
 function bindLocal(v,file){try{if(!file)return;const ext=String(file.name||'').toLowerCase(),kind=/\.(mp4|webm|mov|mkv|m4v)$/.test(ext)?'video':/\.(png|jpe?g|webp|avif|gif)$/.test(ext)?'image':'';if(!kind)throw Error();const previewOnly=v.result?.filename===file.name&&v.result.kind===kind;const next=previewOnly?current:attachTrialResult(current,v.id,{filename:file.name,kind});const url=URL.createObjectURL(file);release(v.id);previews.set(v.id,{url,local:true});current=next;save();render();}catch{notify('invalid');}}
 function arm(v){armed={projectId:current.id,variantId:v.id};const heading=document.getElementById('catalog-title');if(heading){for(let n=heading;n;n=n.parentElement)if(n.tagName==='DETAILS')n.open=true;heading.scrollIntoView({behavior:'smooth',block:'start'});}statusKey='';status.textContent=t().armed+v.title;}
 function refreshCompare(){if(!compareSelectA)return;const candidates=current.variants.filter(v=>v.result?.actual?.id);for(const select of [compareSelectA,compareSelectB])select.replaceChildren(new Option('—',''),...candidates.map(v=>new Option(v.title+' · '+v.result.filename,v.id)));compareSelectA.value=compareA;compareSelectB.value=compareB;const a=current.variants.find(v=>v.id===compareA)?.result?.actual?.id,b=current.variants.find(v=>v.id===compareB)?.result?.actual?.id;compareButton.disabled=!a||!b||a===b;}
 function refreshCards(){for(const view of views){const v=current.variants.find(x=>x.id===view.id);if(!v)continue;const prompt=trialPrompt(current,v);if(view.prompt.value!==prompt)view.prompt.value=prompt;view.manual.textContent=trialManualStale(current,v)?t().manualStale:'';view.result.textContent=v.result?.filename||'—';view.stale.textContent=trialResultStale(current,v)?t().stale:'';view.decision.value=v.decision;view.decision.disabled=!v.result;view.recipe.disabled=!v.result||v.decision!=='works'||trialResultStale(current,v);view.clear.disabled=!v.result;}refreshCompare();}
 function render(){summary.textContent=t().title;launcher.textContent=t().title;fields.clear();views=[];body.replaceChildren(el('p',t().intro));const toolbar=el('div','','tb-actions');body.append(toolbar);projectSelect=field(toolbar,'projects',current.id,'select',id=>{const p=store.list().find(p=>p.id===id);if(p&&canLeave())select(p);else projectSelect.value=current.id;});updateProjects();button(toolbar,'new',()=>{if(canLeave()){select(createTrialProject(current.axis,current.mode));save();}});button(toolbar,'save',save);button(toolbar,'remove',()=>{if(!globalThis.confirm(t().confirmRemove))return;try{store.remove(current.id);select(store.list().at(-1)||createTrialProject());emit('prompt-studio-work-changed');}catch{notify('failed');}});
  const title=field(body,'name',current.title,'text',value=>changed(()=>current.title=value));title.maxLength=120;const controls=el('div','','tb-controls');body.append(controls);field(controls,'mode',current.mode,'select',value=>{if(value==='image'&&current.axis==='motion'){if(!globalThis.confirm(t().replace)){fields.get('mode').value=current.mode;return;}clearPreviews();current.axis='lighting';current.variants=createTrialProject('lighting','image').variants;armed=null;}current.mode=value;save();render();},['image','video']);field(controls,'axis',current.axis,'select',value=>{if(!globalThis.confirm(t().replace)){fields.get('axis').value=current.axis;return;}clearPreviews();current.axis=value;current.variants=createTrialProject(value,current.mode).variants;armed=null;save();render();},trialAxes.filter(x=>current.mode==='video'||x!=='motion'));button(controls,'presets',()=>{if(!globalThis.confirm(t().replace))return;clearPreviews();current.variants=createTrialProject(current.axis,current.mode).variants;armed=null;save();render();});
  const common=el('details','','tb-common');common.open=true;common.append(el('summary',t().common));body.append(common);common.append(el('p',t().sceneHelp,'tb-help'));for(const key of ['scene','lighting','style','framing','motion','action','negative']){if(current.mode==='image'&&['motion','action'].includes(key))continue;if(key===current.axis)continue;const n=field(common,key,current.base[key]||'','textarea',value=>changed(()=>current.base[key]=value));n.maxLength=key==='scene'?12000:key==='negative'?6000:3000;}
  const settings=el('details','','tb-common');settings.append(el('summary',t().settings),el('p',t().settingsHelp,'tb-help'));const settingGrid=el('div','','tb-controls');settings.append(settingGrid);body.append(settings);for(const key of ['model','width','height','seed',...(current.mode==='video'?['seconds']:[])]){const input=field(settingGrid,key,current.base[key],key==='model'?'text':'number',value=>{if(key==='model')changed(()=>current.base.model=value);else if(value===''||Number.isFinite(Number(value))&&Number(value)>=0&&Number(value)<=(key==='seed'?Number.MAX_SAFE_INTEGER:key==='seconds'?60:16384))changed(()=>current.base[key]=value===''?'':Number(value));});if(key!=='model'){input.min='0';input.max=String(key==='seed'?Number.MAX_SAFE_INTEGER:key==='seconds'?60:16384);input.step='1';}}
  body.append(el('p',t().mediaHelp,'tb-help'),el('p',t().mediaReuse,'tb-help'));const grid=el('div','','tb-grid');body.append(grid);
  for(const variant of current.variants){const id=variant.id,card=el('article','','tb-card');card.dataset.tbVariant=id;const get=()=>current.variants.find(v=>v.id===id);const heading=field(card,'variant',variant.title,'text',value=>changed(()=>get().title=value));heading.maxLength=120;const direction=field(card,'direction',variant.direction,'textarea',value=>changed(()=>get().direction=value));direction.maxLength=3000;const prompt=field(card,'prompt',trialPrompt(current,variant),'textarea',value=>changed(()=>{const v=get();v.customPrompt=value;v.customBasis=trialBasis(current,v);}));prompt.rows=7;prompt.maxLength=24000;const manual=el('p','','tb-warning');card.append(manual);const actions=el('div','','tb-actions');card.append(actions);button(actions,'copy',()=>copy(trialPrompt(current,get())));button(actions,'copyNegative',()=>copy(current.base.negative));button(actions,'rebuild',()=>{if(get().customPrompt!==null&&!globalThis.confirm(t().confirmRebuild))return;changed(()=>{get().customPrompt=null;get().customBasis='';});});
   const drop=el('div','','tb-drop'),input=el('input');input.type='file';input.accept='image/png,image/jpeg,image/webp,image/avif,image/gif,video/mp4,video/webm,video/quicktime,.mkv';input.hidden=true;input.dataset.tbFile=id;drop.append(input);button(drop,'attach',()=>input.click());input.addEventListener('change',()=>{bindLocal(get(),input.files?.[0]);input.value='';});drop.addEventListener('dragover',e=>e.preventDefault());drop.addEventListener('drop',e=>{e.preventDefault();bindLocal(get(),e.dataTransfer?.files?.[0]);});button(drop,'archive',()=>arm(get()));card.append(drop);const result=el('p','','tb-filename'),preview=el('div','','tb-preview'),stale=el('p','','tb-warning');card.append(result,preview,stale);showPreview(preview,variant);const clear=button(card,'clear',()=>{release(id);changed(()=>{get().result=null;get().decision='planned';});preview.replaceChildren();});const decision=field(card,'decision',variant.decision,'select',value=>changed(()=>get().decision=value),trialDecisions);const note=field(card,'note',variant.note,'textarea',value=>changed(()=>get().note=value));note.maxLength=2000;const recipe=button(card,'recipe',()=>{try{const packet=trialRecipe(current,id);onRecipe(packet.item,packet.notes);}catch{notify('invalid');}});card.append(el('p',t().recipeHelp,'tb-help'));const remove=button(card,'removeVariant',()=>{if(!globalThis.confirm(t().replace))return;release(id);current.variants=current.variants.filter(v=>v.id!==id);save();render();});remove.disabled=current.variants.length<=2;views.push({id,prompt,manual,result,stale,decision,recipe,clear});grid.append(card);}
  const add=button(body,'add',()=>{if(current.variants.length>=6){notify('limit');return;}const v=createTrialProject(current.axis,current.mode).variants[0];v.title=t().variant;v.direction='';current.variants.push(v);save();render();});add.disabled=current.variants.length>=6;
  const comparison=el('div','','tb-comparison');comparison.append(el('p',t().compareHelp));body.append(comparison);compareSelectA=field(comparison,'A',compareA,'select',value=>{compareA=value;refreshCompare();});compareSelectB=field(comparison,'B',compareB,'select',value=>{compareB=value;refreshCompare();});compareButton=button(comparison,'compare',async()=>{const a=current.variants.find(v=>v.id===compareA)?.result?.actual?.id,b=current.variants.find(v=>v.id===compareB)?.result?.actual?.id;if(!a||!b||a===b)return;compareButton.disabled=true;try{if(!await onCompare(a,b))notify('compareFailed');}catch{notify('compareFailed');}finally{refreshCompare();}});
  const exports=el('div','','tb-actions');body.append(exports);button(exports,'export',()=>download(serializeTrial(current),'json'));button(exports,'text',()=>download(exportTrialText(current),'txt'));const importer=el('input');importer.type='file';importer.accept='.json,application/json';importer.hidden=true;exports.append(importer);button(exports,'import',()=>{importer.value='';importer.click();});importer.addEventListener('change',async()=>{try{const file=importer.files?.[0];if(!file||file.size>500000)throw Error();const p=parseTrial(await file.text());if(!canLeave())return;select(p);save();}catch{notify('invalid');}});body.append(status);status.textContent=t()[statusKey]||'';refreshCards();
 }
 function captureArchive(item){if(!armed||armed.projectId!==current.id||!current.variants.some(v=>v.id===armed.variantId)){open();notify('chooseTarget');return false;}try{const id=armed.variantId;current=attachTrialResult(current,id,{filename:item.filename,kind:item.kind},item);release(id);previews.set(id,{url:'/api/catalog/media?id='+encodeURIComponent(item.id),local:false});armed=null;save();render();open();return true;}catch{notify('invalid');return false;}}
 function list(){const fresh=createTrialStore(storage);if(fresh.problem())throw Error('storage');return fresh.list();}
 function resume(id){if(!canLeave())return false;try{const fresh=createTrialStore(storage);if(fresh.problem())throw Error();const p=fresh.list().find(p=>p.id===id);if(!p)return false;store=fresh;select(p);open();return true;}catch{notify('failed');return false;}}
 document.getElementById('ui-language')?.addEventListener('change',render);globalThis.addEventListener?.('beforeunload',event=>{if(pending){event.preventDefault();event.returnValue='';}});render();return {isResultStale:trialResultStale,getState:()=>normalizeTrialProject(current),list,resume,labels:t,captureArchive,translate:render,open};
}
